17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.Comparator;
23	import java.util.List;
24	import java.util.Locale;
25	import java.util.Map;
26	import java.util.regex.Pattern;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
34	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
37	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
38	import org.springframework.samples.petclinic.mapper.OwnerMapper;
39	import org.springframework.samples.petclinic.mapper.PetMapper;
40	import org.springframework.samples.petclinic.mapper.VisitMapper;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.samples.petclinic.util.Soundex;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.util.StringUtils;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner's email. An email whose domain
81	     * (the part after the {@code @}, compared case-insensitively) is on this blocklist is rejected.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
84	        "mailinator.com",
85	        "tempmail.com",
86	        "guerrillamail.com");
87	
88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code and registration date so the side-effect can be observed
91	     * independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Dedicated notification logger. Successful owner creation enqueues a welcome notification here,
97	     * a single line carrying the new owner's id and memberId, so the side-effect can be observed
98	     * independently of the HTTP response.
99	     */
100	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
101	
102	    /**
103	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
104	     * audit event. Shared across every create handled by this singleton controller and incremented
105	     * once per successful owner creation, so the events form a strictly ordered, gap-free stream.
106	     */
107	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
108	        new java.util.concurrent.atomic.AtomicLong();
109	
110	    /**
111	     * Common street-type abbreviations expanded during address normalization. Keys and values are
112	     * upper-cased so the mapping is applied after the address has been upper-cased.
113	     */
114	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
115	        "ST", "STREET",
116	        "RD", "ROAD",
117	        "AVE", "AVENUE");
118	
119	    /**
120	     * Maximum number of owners permitted in a single city. Once a city already contains this many
121	     * owners, creating another owner in that city is rejected as a conflict.
122	     */
123	    private static final int CITY_CAPACITY = 50;
124	
125	    /**
126	     * Number of owners a city must already contain for a newly created owner in it to be flagged with
127	     * {@code capacityWarning=true}. Once a city holds at least this many owners (but fewer than the
128	     * {@value #CITY_CAPACITY} hard limit), the next owner in that city signals it is approaching
129	     * capacity; the create itself still succeeds.
130	     */
131	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
132	
133	    /**
134	     * Fixed list of public holidays. A registration date that, after the weekend adjustment, lands on
135	     * one of these dates is rolled forward to the next non-holiday business day.
136	     */
137	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
138	        LocalDate.of(2026, 1, 1),
139	        LocalDate.of(2026, 1, 26),
140	        LocalDate.of(2026, 4, 25),
141	        LocalDate.of(2026, 12, 25),
142	        LocalDate.of(2026, 12, 28));
143	
144	    /**
145	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
146	     * already share the current registration date, creating another owner today is rejected.
147	     */
148	    private static final int DAILY_OWNER_LIMIT = 100;
149	
150	    /**
151	     * Number of owner registrations on a single business day above which a newly created owner is
152	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
153	     * registration date, the surge is signalled in the response; the create itself still succeeds.
154	     */
155	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
156	
157	    /**
158	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
159	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
160	     * a city that is not listed has no known region and accepts any 4-digit postcode.
161	     */
162	    private static final Map<String, String> CITY_REGIONS = Map.of(
163	        "Sydney", "NSW",
164	        "Melbourne", "VIC",
165	        "Brisbane", "QLD");
166	
167	    /**
168	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
169	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
170	     */
171	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
172	        "NSW", new int[] {2000, 2099},
173	        "VIC", new int[] {3000, 3099},
174	        "QLD", new int[] {4000, 4099});
175	
176	    /**
177	     * Request header carrying the client-supplied idempotency key. When a create request repeats with
178	     * a key that has already produced an owner, the original owner is returned with {@code 200 OK}
179	     * instead of creating a duplicate.
180	     */
181	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
182	
183	    /**
184	     * Maps a previously seen {@code Idempotency-Key} to the id of the owner it created, so a repeated
185	     * create with the same key resolves to the originally created owner rather than creating a
186	     * duplicate. Kept in memory for the lifetime of this singleton controller and safe for concurrent
187	     * access across requests.
188	     */
189	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
190	
191	    private final ClinicService clinicService;
192	
193	    private final OwnerMapper ownerMapper;
194	
195	    private final PetMapper petMapper;
196	
197	    private final VisitMapper visitMapper;
198	
199	    private final jakarta.servlet.http.HttpServletRequest request;
200	
201	    public OwnerRestControllerV1(ClinicService clinicService,
202	                                 OwnerMapper ownerMapper,
203	                                 PetMapper petMapper,
204	                                 VisitMapper visitMapper,
205	                                 jakarta.servlet.http.HttpServletRequest request) {
206	        this.clinicService = clinicService;
207	        this.ownerMapper = ownerMapper;
208	        this.petMapper = petMapper;
209	        this.visitMapper = visitMapper;
210	        this.request = request;
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
216	        Collection<Owner> owners;
217	        if (lastName != null) {
218	            owners = this.clinicService.findOwnerByLastName(lastName);
219	        } else {
220	            owners = this.clinicService.findAllOwners();
221	        }
222	        if (owners.isEmpty()) {
223	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	        }
225	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner == null) {
233	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	        }
235	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
236	    }
237	
238	    /**
239	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
240	     * upper-cases the value, and expands common street-type abbreviations word-by-word
241	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
242	     * normalizes to the empty string. The normalized value is what the application stores, returns
243	     * and compares for household detection.
244	     *
245	     * @param address the raw address value from the request, may be {@code null}
246	     * @return the normalized address, or the empty string when none was supplied
247	     */
248	    private String normalizeAddress(String address) {
249	        if (address == null) {
250	            return "";
251	        }
252	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
253	        if (collapsed.isEmpty()) {
254	            return "";
255	        }
256	        String[] tokens = collapsed.split(" ");
257	        StringBuilder normalized = new StringBuilder();
258	        for (int i = 0; i < tokens.length; i++) {
259	            if (i > 0) {
260	                normalized.append(' ');
261	            }
262	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
263	        }
264	        return normalized.toString();
265	    }
266	
267	    /**
268	     * Applies address normalization to whichever address form the request supplied, preferring the
269	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
270	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
271	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
272	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
273	     * appended - so everything downstream that reads {@code address} sees the structured value. When
274	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
275	     * earlier minimal owners backward-compatible.
276	     *
277	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
278	     */
279	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
280	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
281	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
282	            ownerFieldsDto.setAddressLine1(line1);
283	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
284	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
285	                ownerFieldsDto.setAddressLine2(line2);
286	                ownerFieldsDto.setAddress(line1 + " " + line2);
287	            } else {
288	                ownerFieldsDto.setAddressLine2(null);
289	                ownerFieldsDto.setAddress(line1);
290	            }
291	        } else {
292	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
293	        }
294	    }
295	
296	    /**
297	     * Rejects an owner payload that is missing or blank in any required field. The response body's
298	     * {@code errors} array lists the name of each offending field.
299	     *
300	     * @param ownerFieldsDto the owner payload to validate
301	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
302	     */
303	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
304	        List<String> missingFields = new ArrayList<>();
305	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
306	            missingFields.add("firstName");
307	        }
308	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
309	            missingFields.add("lastName");
310	        }
311	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
312	            missingFields.add("address");
313	        }
314	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
315	            missingFields.add("city");
316	        }
317	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
318	            missingFields.add("telephone");
319	        }
320	        if (!missingFields.isEmpty()) {
321	            throw new RequiredFieldsMissingException(missingFields);
322	        }
323	    }
324	
325	    /**
326	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
327	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
328	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
329	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
330	     * region accepts any 4-digit postcode.
331	     *
332	     * @param postcode the raw postcode value from the request, may be {@code null}
333	     * @param city the owner's city, used to look up the region whose range constrains the postcode
334	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
335	     */
336	    private void validatePostcode(String postcode, String city) {
337	        if (postcode == null) {
338	            return;
339	        }
340	        if (!postcode.matches("[0-9]{4}")) {
341	            throw new InvalidFieldsException(List.of("postcode"));
342	        }
343	        String region = CITY_REGIONS.get(city);
344	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
345	        if (range != null) {
346	            int value = Integer.parseInt(postcode);
347	            if (value < range[0] || value > range[1]) {
348	                throw new InvalidFieldsException(List.of("postcode"));
349	            }
350	        }
351	    }
352	
353	    /**
354	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
355	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
356	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
357	     * followed by 8 to 15 digits.
358	     *
359	     * @param telephone the raw telephone value from the request
360	     * @return the E.164 telephone (e.g. {@code +61412345678})
361	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
362	     */
363	    private String normalizeTelephone(String telephone) {
364	        if (telephone == null) {
365	            throw new InvalidFieldsException(List.of("telephone"));
366	        }
367	        String trimmed = telephone.trim();
368	        boolean international = trimmed.startsWith("+");
369	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
370	        String digits;
371	        if (international) {
372	            digits = cleaned.substring(1);
373	        } else {
374	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
375	            digits = "61" + national;
376	        }
377	        if (!digits.matches("[0-9]{8,15}")) {
378	            throw new InvalidFieldsException(List.of("telephone"));
379	        }
380	        requireValidNationalLength(digits);
381	        return "+" + digits;
382	    }
383	
384	    /**
385	     * Country codes with a fixed national-number length, checked longest-prefix first so that
386	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
387	     * digits; the North American Numbering Plan ('1') requires 10.
388	     */
389	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
390	
391	    /**
392	     * Validates that the national number (the E.164 digits after the country code) has the length
393	     * required for its country. Country codes without a known fixed length are left to the general
394	     * E.164 length check.
395	     *
396	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
397	     * @throws InvalidFieldsException if the national number is the wrong length for its country
398	     */
399	    private void requireValidNationalLength(String digits) {
400	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
401	            .filter(entry -> digits.startsWith(entry.getKey()))
402	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
403	            .ifPresent(entry -> {
404	                int nationalLength = digits.length() - entry.getKey().length();
405	                if (nationalLength != entry.getValue()) {
406	                    throw new InvalidFieldsException(List.of("telephone"));
407	                }
408	            });
409	    }
410	
411	    /**
412	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
413	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
414	     * be a syntactically valid address; the accepted value is returned lower-cased.
415	     *
416	     * @param email the raw email value from the request, may be {@code null}
417	     * @return the lower-cased email, or {@code null} when none was supplied
418	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
419	     */
420	    private String normalizeEmail(String email) {
421	        if (email == null || email.isBlank()) {
422	            return null;
423	        }
424	        String trimmed = email.trim();
425	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
426	            throw new InvalidFieldsException(List.of("email"));
427	        }
428	        String normalized = trimmed.toLowerCase(Locale.ROOT);
429	        String domain = normalized.substring(normalized.indexOf('@') + 1);
430	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
431	            throw new InvalidFieldsException(List.of("email"));
432	        }
433	        return normalized;
434	    }
435	
436	    /**
437	     * Tests whether an existing owner is not soft-deleted, so that duplicate and identity detection
438	     * can ignore owners flagged {@code deleted}. An owner whose {@code deleted} flag is {@code null}
439	     * or {@code false} is considered active; only an explicit {@code true} excludes it.
440	     *
441	     * @param owner an existing owner from the data store
442	     * @return {@code true} when the owner is not flagged deleted, otherwise {@code false}
443	     */
444	    private static boolean isNotDeleted(Owner owner) {
445	        return !Boolean.TRUE.equals(owner.getDeleted());
446	    }
447	
448	    private void requireUniqueIdentity(Owner owner) {
449	        String identityKey = ownerMapper.identityKey(owner);
450	        boolean taken = this.clinicService.findAllOwners().stream()
451	            .filter(OwnerRestControllerV1::isNotDeleted)
452	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
453	        if (taken) {
454	            throw new DuplicateOwnerIdentityException(identityKey);
455	        }
456	    }
457	
458	    /**
459	     * Computes the membership level ceiling for the owner being created: one above the current
460	     * maximum membership level among the existing members of the owner's household (those sharing its
461	     * computed {@link OwnerMapper#householdId(Owner) household id}, ignoring soft-deleted owners). Each
462	     * existing member's level is evaluated for the household size that now includes the joining owner,
463	     * so the ceiling reflects the household's up-to-date standing. Returns {@code null} when the
464	     * household has no existing member, in which case no cap applies. Invoked before the new owner is
465	     * persisted, so it never counts the owner itself.
466	     *
467	     * @param owner the owner being created, with its normalized fields already applied
468	     * @return the capped maximum membership level, or {@code null} when no existing household member
469	     */
470	    private Integer householdMembershipLevelCap(Owner owner) {
471	        String householdId = ownerMapper.householdId(owner);
472	        List<Owner> members = this.clinicService.findAllOwners().stream()
473	            .filter(OwnerRestControllerV1::isNotDeleted)
474	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
475	            .toList();
476	        if (members.isEmpty()) {
477	            return null;
478	        }
479	        int householdSize = members.size() + 1;
480	        int maxLevel = members.stream()
481	            .mapToInt(existing -> ownerMapper.householdMemberLevel(existing, householdSize))
482	            .max()
483	            .getAsInt();
484	        return maxLevel + 1;
485	    }
486	
487	    /**
488	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
489	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
490	     * normalizes to the empty string.
491	     *
492	     * @param value the raw field value, may be {@code null}
493	     * @return the trimmed, whitespace-collapsed, lower-cased form
494	     */
495	    private String normalizeHousehold(String value) {
496	        if (value == null) {
497	            return "";
498	        }
499	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
500	    }
501	
502	    /**
503	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
504	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}, so its
505	     * identity key differs from the new owner's) but shares the new owner's surname phonetically -
506	     * the same {@link Soundex Soundex} code for the last name - and the same postcode. Only owners
507	     * with a postcode participate: when the new owner has no postcode there is nothing to soft-match
508	     * on. When several existing owners match, the one with the lowest id is returned so the result is
509	     * deterministic.
510	     *
511	     * @param owner the owner being created, with its normalized telephone already applied
512	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
513	     */
514	    private Owner findPossibleDuplicate(Owner owner) {
515	        String lastName = owner.getLastName();
516	        String postcode = owner.getPostcode();
517	        if (lastName == null || postcode == null) {
518	            return null;
519	        }
520	        String soundex = Soundex.encode(lastName);
521	        String identityKey = ownerMapper.identityKey(owner);
522	        return this.clinicService.findAllOwners().stream()
523	            .filter(OwnerRestControllerV1::isNotDeleted)
524	            .filter(existing -> postcode.equals(existing.getPostcode()))
525	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
526	            .filter(existing -> !identityKey.equals(ownerMapper.identityKey(existing)))
527	            .min(Comparator.comparingInt(Owner::getId))
528	            .orElse(null);
529	    }
530	
531	    /**
532	     * Rejects an owner whose city already contains the maximum permitted number of owners
533	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
534	     * the same normalization used for the other owner household fields.
535	     *
536	     * @param city the city of the owner being created
537	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
538	     */
539	    private void requireCityHasCapacity(String city) {
540	        String normalizedCity = normalizeHousehold(city);
541	        long count = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
543	            .count();
544	        if (count >= CITY_CAPACITY) {
545	            throw new CityAtCapacityException(city);
546	        }
547	    }
548	
549	    /**
550	     * Determines whether creating an owner in the given city is approaching the per-city capacity
551	     * limit: {@code true} when the city already contains between {@value #CITY_CAPACITY_WARNING_THRESHOLD}
552	     * and {@value #CITY_CAPACITY} (exclusive) owners. Cities are compared case-insensitively with
553	     * collapsed whitespace, matching {@link #requireCityHasCapacity(String)}. Evaluated before the new
554	     * owner is persisted, so the count reflects the owners that existed at the time of creation; the
555	     * hard rejection at {@value #CITY_CAPACITY} has already run, so the count seen here is below it.
556	     *
557	     * @param city the city of the owner being created
558	     * @return {@code true} when the city already holds 40-49 owners, otherwise {@code false}
559	     */
560	    private boolean isApproachingCityCapacity(String city) {
561	        String normalizedCity = normalizeHousehold(city);
562	        long count = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
564	            .count();
565	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
566	    }
567	
568	    /**
569	     * Rejects creating an owner once the given business day has already reached the maximum
570	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
571	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
572	     * registration date.
573	     *
574	     * @param registrationDate the business-day-adjusted registration date of the owner being created
575	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
576	     *     registered on that business day
577	     */
578	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
579	        long count = this.clinicService.findAllOwners().stream()
580	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
581	            .count();
582	        if (count >= DAILY_OWNER_LIMIT) {
583	            throw new DailyOwnerLimitException(registrationDate);
584	        }
585	    }
586	
587	    /**
588	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
589	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
590	     * been registered on that date. Evaluated before the new owner is persisted, so the count
591	     * reflects the owners that existed at the time of creation.
592	     *
593	     * @param registrationDate the business-day-adjusted registration date of the owner being created
594	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
595	     *     that registration date, otherwise {@code false}
596	     */
597	    private boolean isBulkSignup(LocalDate registrationDate) {
598	        long count = this.clinicService.findAllOwners().stream()
599	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
600	            .count();
601	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
602	    }
603	
604	    /**
605	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
606	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
607	     * date in the future is invalid.
608	     *
609	     * @param registrationDate the registration date supplied on the request, may be {@code null}
610	     * @throws InvalidFieldsException if the supplied date is later than today's server date
611	     */
612	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
613	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
614	            throw new InvalidFieldsException(List.of("registrationDate"));
615	        }
616	    }
617	
618	    /**
619	     * Rolls a registration date forward onto a business day: any Saturday, Sunday or listed public
620	     * holiday is advanced day by day until the first weekday that is not a public holiday, while a
621	     * plain weekday is returned unchanged.
622	     *
623	     * @param date the effective registration date (supplied or defaulted to the server date)
624	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
625	     */
626	    private LocalDate toBusinessDay(LocalDate date) {
627	        LocalDate result = date;
628	        while (isWeekend(result) || PUBLIC_HOLIDAYS.contains(result)) {
629	            result = result.plusDays(1);
630	        }
631	        return result;
632	    }
633	
634	    private boolean isWeekend(LocalDate date) {
635	        return switch (date.getDayOfWeek()) {
636	            case SATURDAY, SUNDAY -> true;
637	            default -> false;
638	        };
639	    }
640	
641	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
642	    @Override
643	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
644	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
645	        if (StringUtils.hasText(idempotencyKey)) {
646	            Integer existingId = idempotentCreates.get(idempotencyKey);
647	            if (existingId != null) {
648	                Owner existing = this.clinicService.findOwnerById(existingId);
649	                if (existing != null) {
650	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
651	                }
652	            }
653	        }
654	        applyAddressFields(ownerFieldsDto);
655	        validateRequiredFields(ownerFieldsDto);
656	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
657	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
658	        requireCityHasCapacity(ownerFieldsDto.getCity());
659	        String email = normalizeEmail(ownerFieldsDto.getEmail());
660	        HttpHeaders headers = new HttpHeaders();
661	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
662	        owner.setTelephone(telephone);
663	        owner.setEmail(email);
664	        owner.setDeleted(false);
665	        requireUniqueIdentity(owner);
666	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
667	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
668	        LocalDate effectiveDate = owner.getRegistrationDate() != null
669	            ? owner.getRegistrationDate() : LocalDate.now();
670	        LocalDate registrationDate = toBusinessDay(effectiveDate);
671	        owner.setRegistrationDate(registrationDate);
672	        requireDailyLimitNotReached(registrationDate);
673	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
674	        owner.setCapacityWarning(isApproachingCityCapacity(ownerFieldsDto.getCity()));
675	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
676	        owner.setPossibleDuplicate(possibleDuplicate != null);
677	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
678	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner));
679	        this.clinicService.saveOwner(owner);
680	        if (StringUtils.hasText(idempotencyKey)) {
681	            idempotentCreates.put(idempotencyKey, owner.getId());
682	        }
683	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
684	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
685	            ownerMapper.membershipLevel(owner));
686	        AUDIT.info("{}", new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
687	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner)).toJson());
688	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
689	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
690	        headers.setLocation(UriComponentsBuilder.newInstance()
691	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
692	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
693	    }
694	
695	    /**
696	     * The owner's primary identifier as carried by the structured {@code OWNER_CREATED} audit event:
697	     * the unified {@code memberId}, into which the former {@code customerCode} has been folded.
698	     */
699	    private String primaryIdentifier(Owner owner) {
700	        return owner.getMemberId();
701	    }
702	
703	    /**
704	     * Immutable structured record of a successful owner creation, serialized as a single JSON object
705	     * to the {@code AUDIT} logger alongside the human-readable audit line. The {@code memberId}
706	     * field carries the owner's primary identifier (see {@link #primaryIdentifier(Owner)}).
707	     */
708	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
709	                                     Integer membershipLevel) {
710	
711	        String toJson() {
712	            return "{\"seq\":" + seq
713	                + ",\"ownerId\":" + ownerId
714	                + ",\"memberId\":" + jsonString(memberId)
715	                + ",\"membershipLevel\":" + membershipLevel
716	                + ",\"event\":\"OWNER_CREATED\"}";
717	        }
718	
719	        private static String jsonString(String value) {
720	            if (value == null) {
721	                return "null";
722	            }
723	            StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
724	            for (int i = 0; i < value.length(); i++) {
725	                char c = value.charAt(i);
726	                switch (c) {
727	                    case '"' -> sb.append("\\\"");
728	                    case '\\' -> sb.append("\\\\");
729	                    case '\n' -> sb.append("\\n");
730	                    case '\r' -> sb.append("\\r");
731	                    case '\t' -> sb.append("\\t");
732	                    default -> {
733	                        if (c < 0x20) {
734	                            sb.append(String.format("\\u%04x", (int) c));
735	                        } else {
736	                            sb.append(c);
737	                        }
738	                    }
739	                }
740	            }
741	            return sb.append('"').toString();
742	        }
743	    }
744	
745	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
746	    @Override
747	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
748	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
749	        if (currentOwner == null) {
750	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	        }
752	        currentOwner.setAddress(ownerFieldsDto.getAddress());
753	        currentOwner.setCity(ownerFieldsDto.getCity());
754	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
755	        currentOwner.setLastName(ownerFieldsDto.getLastName());
756	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
757	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
758	        this.clinicService.saveOwner(currentOwner);
759	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
760	    }
761	
762	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
763	    @Transactional
764	    @Override
765	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
766	        Owner owner = this.clinicService.findOwnerById(ownerId);
767	        if (owner == null) {
768	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
769	        }
770	        owner.setDeleted(true);
771	        this.clinicService.saveOwner(owner);
772	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
773	    }
774	
775	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
776	    @Override
777	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
778	        Owner owner = this.clinicService.findOwnerById(ownerId);
779	        if (owner == null) {
780	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
781	        }
782	        HttpHeaders headers = new HttpHeaders();
783	        Pet pet = petMapper.toPet(petFieldsDto);
784	        owner.setId(ownerId);
785	        pet.setOwner(owner);
786	        pet.getType().setName(null);
787	        this.clinicService.savePet(pet);
788	        PetDto petDto = petMapper.toPetDto(pet);
789	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
790	            .buildAndExpand(pet.getId()).toUri());
791	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
792	    }
793	
794	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
795	    @Override
796	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
797	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
798	        if (currentOwner != null) {
799	            Pet currentPet = this.clinicService.findPetById(petId);
800	            if (currentPet != null) {
801	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
802	                currentPet.setName(petFieldsDto.getName());
803	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
804	                this.clinicService.savePet(currentPet);
805	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
806	            }
807	        }
