826	
827	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
828	    @Override
829	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
830	        Owner owner = this.clinicService.findOwnerById(ownerId);
831	        if (owner != null) {
832	            Pet pet = owner.getPet(petId);
833	            if (pet != null) {
834	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
