42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /**
47	     * Derives a link to the owner's own resource, formatted {@code /api/owners/<id>} where
48	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet, so the
49	     * field is omitted from the response.
50	     *
51	     * @param owner the owner to derive the self link for
52	     * @return the {@code /api/owners/<id>} self link, or {@code null} when the owner has no id
53	     */
54	    default String selfLink(Owner owner) {
55	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
56	    }
57	
58	    /**
59	     * Derives an owner's salutation from its optional title and last name: {@code "<title> <lastName>"}
60	     * when a non-blank title is present, or just the last name when no title was supplied.
61	     *
62	     * @param owner the owner to derive the salutation for
63	     * @return the composed salutation
64	     */
65	    default String salutation(Owner owner) {
66	        String title = owner.getTitle();
67	        String lastName = owner.getLastName();
68	        if (title == null || title.isBlank()) {
69	            return lastName;
70	        }
71	        return title + " " + lastName;
72	    }
73	
74	    /**
75	     * Derives an owner's age band from its birth date, computed as the owner's age on its
76	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
77	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
78	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
79	     * response.
80	     *
81	     * @param owner the owner to derive the age band for
82	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
83	     *     is held
84	     */
85	    default String ageBand(Owner owner) {
86	        java.time.LocalDate birthDate = owner.getBirthDate();
87	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
88	        if (birthDate == null || registrationDate == null) {
89	            return null;
90	        }
91	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
92	        if (age < 18) {
93	            return "MINOR";
94	        }
95	        return age < 65 ? "ADULT" : "SENIOR";
96	    }
97	
98	    /**
99	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
100	     * email, otherwise {@code "PHONE"}.
101	     *
102	     * @param owner the owner to derive the contact preference for
103	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
104	     */
105	    default String contactPreference(Owner owner) {
106	        String email = owner.getEmail();
107	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
108	    }
109	
110	    /**
111	     * Known telephone country codes, matched longest-prefix first so {@code "61"} is preferred over
112	     * the {@code "1"} it starts with. Mirrors the country codes the create endpoint recognizes when
113	     * normalizing telephones into E.164 form.
114	     */
115	    java.util.List<String> TELEPHONE_COUNTRY_CODES = java.util.List.of("61", "1");
116	
117	    /**
118	     * Formats an owner's stored E.164 telephone for humans: the country code, a space, then the
119	     * national digits grouped in threes (e.g. {@code +61412345678} becomes {@code +61 412 345 678}).
120	     * The country code is taken as the longest recognized prefix (see
121	     * {@link #TELEPHONE_COUNTRY_CODES}), falling back to the leading digit; the raw
122	     * {@link Owner#getTelephone() telephone} stays in E.164 form. A {@code null} or non-E.164 value
123	     * is returned unchanged.
124	     *
125	     * @param owner the owner to format the telephone display for
126	     * @return the human-formatted telephone, or the raw value when it is not a {@code +}-prefixed
127	     *     digit string
128	     */
129	    default String telephoneDisplay(Owner owner) {
130	        String telephone = owner.getTelephone();
131	        if (telephone == null || !telephone.startsWith("+")) {
132	            return telephone;
133	        }
134	        String digits = telephone.substring(1);
135	        if (!digits.matches("[0-9]+")) {
136	            return telephone;
137	        }
138	        String countryCode = TELEPHONE_COUNTRY_CODES.stream()
139	            .filter(digits::startsWith)
140	            .max(java.util.Comparator.comparingInt(String::length))
141	            .orElseGet(() -> digits.substring(0, 1));
142	        String national = digits.substring(countryCode.length());
143	        StringBuilder sb = new StringBuilder("+").append(countryCode);
144	        for (int i = 0; i < national.length(); i += 3) {
145	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
146	        }
147	        return sb.toString();
148	    }
149	
150	    /**
151	     * Derives an owner's locality from the unified member id: the leading {@code <REGION>} segment
152	     * of the owner's {@code memberId}, i.e. the run of letters before the 2-digit fiscal year that
153	     * follows it. Because the member id's region is itself derived from the postcode (falling back
154	     * to the city), the locality moves with the identity rather than being computed independently.
155	     * The result is {@code "UNKNOWN"} when no member id is present.
156	     *
157	     * @param owner the owner to derive the locality for
158	     * @return the region segment of the member id, or {@code "UNKNOWN"}
159	     */
160	    default String locality(Owner owner) {
161	        String memberId = owner.getMemberId();
162	        if (memberId == null || memberId.isEmpty()) {
163	            return "UNKNOWN";
164	        }
165	        int i = 0;
166	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
167	            i++;
168	        }
169	        return i == 0 ? "UNKNOWN" : memberId.substring(0, i);
170	    }
171	
172	    /**
173	     * Fixed region-to-timezone table mapping a canonical region to its IANA timezone name:
174	     * {@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}.
175	     */
176	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
177	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
178	
179	    /**
180	     * The regions considered {@code METRO} for the purposes of {@link #ownerSegment(Owner)}: the
181	     * known regions {@code NSW}, {@code VIC} and {@code QLD}. Any other locality is {@code REGIONAL}.
182	     */
183	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
184	
185	    /**
186	     * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. {@code TIER} is {@code PREMIUM}
187	     * when the owner's {@link #membershipLevel(Owner) membership level} is {@code 3} or more,
188	     * otherwise {@code STANDARD}. {@code AREA} is {@code METRO} when the owner's
189	     * {@link #locality(Owner) locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
190	     * otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
191	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
192	     *
193	     * @param owner the owner to derive the segment for
194	     * @return the {@code <TIER>_<AREA>} owner segment
195	     */
196	    default String ownerSegment(Owner owner) {
197	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
198	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
199	        return tier + "_" + area;
200	    }
201	
202	    /**
203	     * Derives an owner's IANA timezone name from its {@link #locality(Owner) locality/region} using
204	     * the fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
205	     * {@code QLD->Australia/Brisbane}). Returns {@code null} when the region has no known timezone, so
206	     * the field is omitted from the response.
207	     *
208	     * @param owner the owner to derive the timezone for
209	     * @return the region's IANA timezone name, or {@code null} when the region has no known timezone
210	     */
211	    default String timezone(Owner owner) {
212	        return REGION_TIMEZONES.get(locality(owner));
213	    }
214	
215	    /**
216	     * Derives an owner's membership points. Starts at {@code 0}, plus {@code 2} when an email is
217	     * present (non-blank), plus {@code 1} when the owner's namesake count is {@code 0}, plus
218	     * {@code 2} for a household of {@code 3} or more members, plus {@code 3} for a tenure of more
219	     * than one elapsed fiscal year - the number of fiscal years between the owner's registration
220	     * date and the current server date (the fiscal year starts on 1 July). Because a newly created
221	     * owner registers on the current date, its tenure is zero, so a new owner never earns the tenure
222	     * points.
223	     *
224	     * @param owner the owner to derive the membership points for
225	     * @return the membership points, {@code 0} or more
226	     */
227	    default Integer membershipPoints(Owner owner) {
228	        return membershipPoints(owner, owner.getHouseholdMemberCount());
229	    }
230	
231	    /**
232	     * Derives an owner's membership points as {@link #membershipPoints(Owner)}, but scoring the
233	     * household bonus against the supplied household member count rather than the owner's stored one.
234	     * Used to evaluate an existing household member's current standing against the household size that
235	     * includes a newly joining owner.
236	     *
237	     * @param owner the owner to derive the membership points for
238	     * @param householdMemberCount the household member count to score the household bonus against
239	     * @return the membership points, {@code 0} or more
240	     */
241	    private int membershipPoints(Owner owner, Integer householdMemberCount) {
242	        int points = 0;
243	        String email = owner.getEmail();
244	        if (email != null && !email.isBlank()) {
245	            points += 2;
246	        }
247	        Integer namesakeCount = owner.getNamesakeCount();
248	        if (namesakeCount != null && namesakeCount == 0) {
249	            points += 1;
250	        }
251	        if (householdMemberCount != null && householdMemberCount >= 3) {
252	            points += 2;
253	        }
254	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
255	        long tenureFiscalYears = registrationDate == null ? 0
256	            : fiscalYearValue(java.time.LocalDate.now()) - fiscalYearValue(registrationDate);
257	        if (tenureFiscalYears > 1) {
258	            points += 3;
259	        }
260	        return points;
261	    }
262	
263	    /**
264	     * Derives an owner's numeric membership level from its {@link #membershipPoints(Owner) membership
265	     * points}: level {@code 1} for {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3},
266	     * {@code 3} for {@code 4}-{@code 5}, and {@code 4} for {@code 6} or more. The points-derived
267	     * level is then capped by the owner's {@link Owner#getMembershipLevelCap() membership level cap}
268	     * when one was recorded at creation - a new owner's level can never exceed one above the highest
269	     * level among the household members that already existed. When no cap was recorded (the owner had
270	     * no existing household member) the points-derived level is returned unchanged.
271	     *
272	     * @param owner the owner to derive the membership level for
273	     * @return the membership level, between {@code 1} and {@code 4}
274	     */
275	    default Integer membershipLevel(Owner owner) {
276	        return cappedLevel(owner, levelForPoints(membershipPoints(owner)));
277	    }
278	
279	    /**
280	     * Derives an existing household member's current membership level as it would stand in a household
281	     * of the supplied size, so a newly joining owner's level ceiling can be measured against the
282	     * up-to-date standing of the members it joins. The member's own {@link Owner#getMembershipLevelCap()
283	     * cap} still applies.
284	     *
285	     * @param owner the existing household member to evaluate
286	     * @param householdMemberCount the household member count that includes the joining owner
287	     * @return the member's capped membership level for that household size, between {@code 1} and {@code 4}
288	     */
289	    default Integer householdMemberLevel(Owner owner, int householdMemberCount) {
290	        return cappedLevel(owner, levelForPoints(membershipPoints(owner, householdMemberCount)));
291	    }
292	
293	    /**
294	     * Applies an owner's {@link Owner#getMembershipLevelCap() membership level cap} to a points-derived
295	     * level: the level is returned unchanged when no cap was recorded, otherwise it is clamped to the
296	     * cap.
297	     *
298	     * @param owner the owner whose cap is applied
299	     * @param level the uncapped points-derived level
300	     * @return the capped level
301	     */
302	    private Integer cappedLevel(Owner owner, int level) {
303	        Integer cap = owner.getMembershipLevelCap();
304	        if (cap != null && level > cap) {
305	            return cap;
306	        }
307	        return level;
308	    }
309	
310	    /**
311	     * Maps membership points to a numeric level: level {@code 1} for {@code 0}-{@code 1} points,
312	     * {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}, and {@code 4} for
313	     * {@code 6} or more.
314	     *
315	     * @param points the membership points
316	     * @return the points-based membership level, between {@code 1} and {@code 4}
317	     */
318	    private Integer levelForPoints(int points) {
319	        if (points <= 1) {
320	            return 1;
321	        }
322	        if (points <= 3) {
323	            return 2;
324	        }
325	        if (points <= 5) {
326	            return 3;
327	        }
328	        return 4;
329	    }
330	
331	    /**
332	     * Derives an owner's fiscal year, formatted {@code FY<YY>} where {@code YY} is the last two
333	     * digits (zero-padded) of the fiscal year that the owner's business-day-adjusted registration
334	     * date falls in. The fiscal year starts on 1 July and is labelled by the calendar year in which
335	     * it ends, so a registration date on or after 1 July belongs to the next year's fiscal year
336	     * (e.g. {@code 2026-08-11 -> FY27}, {@code 2026-01-05 -> FY26}).
337	     *
338	     * @param owner the owner to derive the fiscal year for
339	     * @return the formatted fiscal year
340	     */
341	    default String fiscalYear(Owner owner) {
342	        return String.format("FY%02d", fiscalYearValue(owner.getRegistrationDate()) % 100);
343	    }
344	
345	    /**
346	     * Computes the fiscal year a date falls in as a full four-digit year. The fiscal year starts on
347	     * 1 July and is labelled by the calendar year in which it ends, so a date in July through
348	     * December belongs to the following calendar year's fiscal year and a date in January through
349	     * June belongs to its own calendar year's fiscal year.
350	     *
351	     * @param date the date to compute the fiscal year for
352	     * @return the fiscal year as a four-digit calendar year
353	     */
354	    private int fiscalYearValue(java.time.LocalDate date) {
355	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
356	    }
357	
358	    /**
359	     * Derives an owner's household identifier: the first 12 hex characters of the SHA-256 digest
360	     * over {@code <normalizedLastName>|<postcode>}, where the last name is normalized
361	     * case-insensitively with collapsed whitespace and a missing postcode contributes the empty
362	     * string. Because it is derived deterministically from the last name and postcode, every owner
363	     * that shares those two fields receives the same value - including owners created via the
364	     * {@code sharesHousehold} flag, which by definition have a matching last name and postcode.
365	     *
366	     * @param owner the owner to derive the household identifier for
367	     * @return the 12 upper-case hex character household identifier, never blank
368	     */
369	    default String householdId(Owner owner) {
370	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
371	        String key = normalizeHouseholdField(owner.getLastName()) + '|' + postcode;
372	        try {
373	            byte[] digest = MessageDigest.getInstance("SHA-256")
374	                .digest(key.getBytes(StandardCharsets.UTF_8));
375	            StringBuilder sb = new StringBuilder(12);
376	            for (int i = 0; i < 6; i++) {
377	                sb.append(String.format("%02X", digest[i]));
378	            }
379	            return sb.toString();
380	        }
381	        catch (NoSuchAlgorithmException ex) {
382	            throw new IllegalStateException("SHA-256 not available", ex);
383	        }
384	    }
385	
386	    /**
387	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
388	     * is the full lower-case hex SHA-256 digest over
389	     * {@code <normalizedTelephone>|<email or empty>|<soundex(lastName)>}: the owner's (already E.164
390	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
391	     * and the {@link Soundex Soundex} code of its last name. Two owners are duplicates only when
392	     * their whole identity keys are equal; because the telephone is part of the key, owners sharing a
393	     * surname (same soundex) but holding different telephones have different keys.
394	     *
395	     * @param owner the owner to derive the identity key for
396	     * @return the 64-character lower-case hex identity key
397	     */
398	    default String identityKey(Owner owner) {
399	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
400	        String email = owner.getEmail() == null ? "" : owner.getEmail();
401	        String key = telephone + '|' + email + '|' + Soundex.encode(owner.getLastName());
402	        try {
403	            byte[] digest = MessageDigest.getInstance("SHA-256")
404	                .digest(key.getBytes(StandardCharsets.UTF_8));
405	            StringBuilder sb = new StringBuilder(digest.length * 2);
406	            for (byte b : digest) {
407	                sb.append(String.format("%02x", b));
408	            }
409	            return sb.toString();
410	        }
411	        catch (NoSuchAlgorithmException ex) {
412	            throw new IllegalStateException("SHA-256 not available", ex);
413	        }
414	    }
415	
416	    /**
417	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
418	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
419	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
420	     *
421	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
422	     * conversion and apply it to unrelated String properties (last name, address, ...).
423	     */
424	    private String normalizeHouseholdField(String value) {
425	        if (value == null) {
426	            return "";
427	        }
428	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
429	    }
430	
431	    Owner toOwner(OwnerDto ownerDto);
432	
433	    @Mapping(target = "id", ignore = true)
434	    @Mapping(target = "pets", ignore = true)
435	    Owner toOwner(OwnerFieldsDto ownerDto);
436	
437	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
438	
439	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
440	
441	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
442	        OwnerPageDto ownerPageDto = new OwnerPageDto();
443	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
444	        ownerPageDto.setPage(ownerPage.getNumber());
445	        ownerPageDto.setSize(ownerPage.getSize());
446	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
447	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
448	        return ownerPageDto;
449	    }
450	}
